def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    size = len(ranks)
    tree = [0] * (size + 1)
    result = []

    for i, value in enumerate(a):
        if i >= k:
            rank = ranks[a[i - k]]
            while rank <= size:
                tree[rank] -= 1
                rank += rank & -rank

        rank = ranks[value]
        prefix = 0
        index = rank
        while index:
            prefix += tree[index]
            index -= index & -index

        result.append(min(i, k) - prefix)

        while rank <= size:
            tree[rank] += 1
            rank += rank & -rank

    return result
